@font-face { font-family: "Bebas Neue"; src: url("/fonts/bebas-neue.woff2") format("woff2"); font-display: swap; }
@font-face { font-family: "Oswald"; font-weight: 400; src: url("/fonts/oswald-400.woff2") format("woff2"); font-display: swap; }
@font-face { font-family: "Oswald"; font-weight: 600; src: url("/fonts/oswald-600.woff2") format("woff2"); font-display: swap; }
@font-face { font-family: "Oswald"; font-weight: 700; src: url("/fonts/oswald-700.woff2") format("woff2"); font-display: swap; }
@font-face { font-family: "Special Elite"; src: url("/fonts/special-elite.woff2") format("woff2"); font-display: swap; }

:root {
  --ink: #080a10;
  --ink-2: #10131c;
  --bone: #eee1c7;
  --bone-dim: #b6a98f;
  --blood: #d74b40;
  --blood-dark: #7c2826;
  --amber: #f2a73b;
  --amber-hot: #ffd36a;
  --teal: #6de0d2;
  --purple: #8274b9;
  --panel: rgba(9, 12, 19, 0.76);
  --line: rgba(238, 225, 199, 0.24);
  --safe-t: max(14px, env(safe-area-inset-top));
  --safe-r: max(16px, env(safe-area-inset-right));
  --safe-b: max(16px, env(safe-area-inset-bottom));
  --safe-l: max(16px, env(safe-area-inset-left));
}

* { box-sizing: border-box; }
html, body {
  width: 100%; height: 100%; margin: 0; overflow: hidden; background: #06070c;
  overscroll-behavior: none; touch-action: none; -webkit-user-select: none; user-select: none;
  -webkit-tap-highlight-color: transparent; -webkit-text-size-adjust: 100%;
}
body { font-family: "Oswald", "Arial Narrow", sans-serif; color: var(--bone); }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; touch-action: manipulation; }
button:focus-visible { outline: 2px solid var(--amber); outline-offset: 3px; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; isolation: isolate; overflow: hidden; background: #06070c; }
#game { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }

.scene-grade, .vignette, .grain, .scanlines, #damage-flash, .low-health-vignette {
  position: absolute; inset: 0; pointer-events: none;
}
.scene-grade {
  z-index: 2;
  background:
    linear-gradient(180deg, rgba(9, 10, 19, 0.2) 0%, transparent 32%, transparent 66%, rgba(7, 7, 11, 0.48) 100%),
    radial-gradient(ellipse at 50% 44%, transparent 38%, rgba(7, 8, 14, 0.45) 100%);
  mix-blend-mode: multiply;
}
.vignette {
  z-index: 6;
  box-shadow: inset 0 0 min(18vw, 240px) min(4vw, 60px) rgba(0, 0, 0, 0.82);
  background: radial-gradient(ellipse at center, transparent 42%, rgba(3, 4, 8, 0.55) 78%, rgba(3, 4, 8, 0.9) 100%);
}
.grain {
  z-index: 30; opacity: 0.075; mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  animation: grain-shift 0.24s steps(2) infinite;
}
@keyframes grain-shift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(-1%, -1%); }
}
.scanlines {
  z-index: 29; opacity: 0.14;
  background: repeating-linear-gradient(180deg, rgba(0,0,0,0.4) 0, rgba(0,0,0,0.4) 1px, transparent 1px, transparent 4px);
  mix-blend-mode: multiply;
}
#damage-flash {
  z-index: 8; opacity: 0; background: radial-gradient(ellipse at center, transparent 26%, rgba(146, 21, 18, 0.5) 70%, rgba(108, 9, 10, 0.88) 100%);
  transition: opacity 0.18s ease;
}
#damage-flash.hit { opacity: 1; transition: opacity 0.04s; }

/* ============ SHARED ============ */
.screen { position: absolute; inset: 0; z-index: 20; }
.modal-screen {
  display: grid; place-items: center;
  background: radial-gradient(ellipse at center, rgba(12, 14, 22, 0.48), rgba(4, 5, 9, 0.9));
  backdrop-filter: blur(7px);
}
.modal-panel {
  position: relative; width: min(440px, calc(100vw - 40px));
  padding: 34px 34px 28px; text-align: center;
  background:
    linear-gradient(135deg, rgba(255,255,255,0.04), transparent 38%),
    rgba(10, 13, 20, 0.93);
  border: 1px solid rgba(238, 225, 199, 0.26);
  box-shadow: 0 30px 90px rgba(0,0,0,0.75), inset 0 0 0 5px rgba(238,225,199,0.035);
}
.modal-panel::before, .modal-panel::after {
  content: ""; position: absolute; left: -1px; right: -1px; height: 5px;
  background: repeating-linear-gradient(115deg, var(--blood) 0 12px, #14151b 12px 24px);
}
.modal-panel::before { top: -6px; }
.modal-panel::after { bottom: -6px; }
.modal-kicker {
  display: inline-block; font-size: 11px; letter-spacing: 0.38em; font-weight: 600;
  color: var(--amber); text-transform: uppercase;
}
.modal-panel h2 {
  font-family: "Bebas Neue", sans-serif; font-size: clamp(42px, 8vw, 66px); font-weight: 400;
  letter-spacing: 0.025em; line-height: 0.9; margin: 12px 0 14px; color: var(--bone);
}
.modal-panel p { margin: 0 0 24px; color: var(--bone-dim); font: 15px/1.5 "Special Elite", serif; letter-spacing: 0.02em; }
.menu-btn {
  display: block; width: 100%; padding: 15px 18px; margin-top: 10px;
  border: 1px solid rgba(238,225,199,0.32); background: rgba(255,255,255,0.025);
  font-size: 15px; letter-spacing: 0.18em; font-weight: 600; transition: background .18s, border-color .18s, transform .18s;
}
.menu-btn:hover { background: rgba(238,225,199,0.08); border-color: var(--bone); }
.menu-btn.primary {
  color: #160f09; background: var(--amber); border-color: var(--amber-hot);
  box-shadow: 0 0 0 4px rgba(242,167,59,0.1), 0 8px 30px rgba(242,167,59,0.18);
}
.menu-btn.primary:hover { background: var(--amber-hot); transform: translateY(-1px); }
.modal-controls { margin-top: 20px; padding-top: 15px; border-top: 1px solid rgba(238,225,199,0.13); font-size: 10px; letter-spacing: .12em; color: rgba(238,225,199,0.45); }

/* ============ TITLE SCREEN ============ */
.start-screen { overflow: hidden; background: radial-gradient(ellipse at 64% 48%, transparent 12%, rgba(6, 7, 12, 0.22) 45%, rgba(5, 6, 10, 0.82) 100%); }
.start-shade {
  position: absolute; inset: 0;
  background:
    linear-gradient(90deg, rgba(6,8,13,0.96) 0%, rgba(6,8,13,0.8) 27%, rgba(6,8,13,0.24) 58%, rgba(6,8,13,0.05) 72%, rgba(6,8,13,0.56) 100%),
    linear-gradient(0deg, rgba(5,6,10,0.96) 0%, transparent 30%, transparent 74%, rgba(5,6,10,0.74) 100%);
}
.start-screen::before {
  content: ""; position: absolute; z-index: 0; inset: 0;
  background:
    radial-gradient(ellipse at 64% 30%, rgba(191, 77, 60, 0.11), transparent 40%),
    repeating-linear-gradient(115deg, transparent 0 118px, rgba(238,225,199,0.021) 118px 119px);
  pointer-events: none;
}
.start-screen::after {
  content: "1959"; position: absolute; right: -1.5vw; top: 9vh; z-index: 0;
  font: 25vw/0.8 "Bebas Neue", sans-serif; color: transparent;
  -webkit-text-stroke: 1px rgba(238, 225, 199, 0.075); letter-spacing: -0.04em; pointer-events: none;
}
.start-marquee {
  position: absolute; top: var(--safe-t); left: var(--safe-l); right: var(--safe-r); z-index: 4;
  display: flex; align-items: center; gap: 16px; max-width: 620px;
  font-size: 9px; font-weight: 600; letter-spacing: 0.34em; color: rgba(238,225,199,0.5);
}
.start-marquee i { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(238,225,199,0.28), transparent); }
.start-marquee span:last-child { color: rgba(215,75,64,0.74); }
.title-wrap {
  position: absolute; z-index: 4; left: var(--safe-l); top: 50%; transform: translateY(-48%);
  width: min(650px, 56vw);
}
.port-badge {
  display: flex; align-items: center; gap: 10px; margin-bottom: 13px;
  font-size: 9px; font-weight: 600; letter-spacing: 0.23em; color: rgba(238,225,199,0.56);
  opacity: 0; animation: title-in .5s .1s ease forwards;
}
.port-badge span { padding: 5px 7px; border: 1px solid rgba(238,225,199,0.3); color: var(--bone); }
.port-badge b { color: var(--amber); font-weight: 600; }
.port-badge i { flex: 0 0 60px; height: 1px; background: rgba(238,225,199,0.26); }
.title-lockup { position: relative; filter: drop-shadow(0 20px 30px rgba(0,0,0,0.55)); }
.title-dead, .title-block {
  display: flex; align-items: flex-start; font-family: "Bebas Neue", sans-serif;
  font-size: clamp(96px, 12.4vw, 196px); line-height: 0.72; letter-spacing: 0.005em;
  color: var(--bone);
  text-shadow:
    0 2px 0 #a18d70, 0 5px 0 #645442, 0 9px 0 #2a2523,
    0 12px 1px rgba(0,0,0,.8), 0 18px 34px rgba(0,0,0,.7);
}
.title-dead span:nth-child(2) { color: var(--amber); transform: translateY(-0.02em); }
.title-dead span:nth-child(4) { color: #c8b797; }
.title-block { margin-top: 2px; font-size: clamp(112px, 14.8vw, 234px); letter-spacing: -0.015em; }
.title-block span:nth-child(2) { color: var(--amber); }
.title-block span:nth-child(3) { color: #f5ead4; }
.title-block span:last-child { color: #b84037; }
.title-dead span, .title-block span {
  display: inline-block; opacity: 0; transform: translateY(-35px) rotate(-3deg);
  animation: letter-slam .42s cubic-bezier(.17,.9,.24,1.2) forwards;
}
.title-dead span:nth-child(1), .title-block span:nth-child(1) { animation-delay: .1s; }
.title-dead span:nth-child(2), .title-block span:nth-child(2) { animation-delay: .16s; }
.title-dead span:nth-child(3), .title-block span:nth-child(3) { animation-delay: .22s; }
.title-dead span:nth-child(4), .title-block span:nth-child(4) { animation-delay: .28s; }
.title-block span:nth-child(5) { animation-delay: .34s; }
@keyframes letter-slam {
  0% { opacity: 0; transform: translateY(-48px) rotate(-7deg) scale(1.14); filter: blur(5px); }
  70% { opacity: 1; transform: translateY(4px) rotate(1deg) scale(.99); filter: blur(0); }
  100% { opacity: 1; transform: translateY(0) rotate(0) scale(1); }
}
.title-slash {
  position: absolute; right: 3%; top: 8%; width: 5px; height: 78%;
  background: var(--blood); transform: rotate(17deg); opacity: 0.8; mix-blend-mode: screen;
  box-shadow: 0 0 26px rgba(215, 75, 64, 0.45);
}
.title-tag {
  position: absolute; left: 2%; bottom: -31px; display: flex; align-items: center; gap: 12px;
  font-size: clamp(15px, 1.8vw, 23px); letter-spacing: 0.48em; font-weight: 400; color: rgba(238,225,199,0.82);
  opacity: 0; animation: title-in .5s .6s ease forwards;
}
.title-tag::before { content: ""; width: 46px; height: 1px; background: var(--blood); }
.title-tag b { color: var(--blood); font-weight: 600; letter-spacing: 0.14em; }
@keyframes title-in { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.title-blurb {
  margin: 49px 0 0; color: rgba(238,225,199,0.62); font: 13px/1.75 "Special Elite", serif;
  letter-spacing: .025em; opacity: 0; animation: title-in .5s .72s ease forwards;
}
.title-blurb strong { color: var(--bone); font-weight: 400; }
.start-actions { margin-top: 24px; display: flex; align-items: center; gap: 26px; opacity: 0; animation: title-in .5s .85s ease forwards; }
.start-btn {
  position: relative; overflow: hidden; min-width: 246px; padding: 15px 28px 13px;
  text-align: left; color: #140e07; background: var(--amber);
  clip-path: polygon(0 0, 98% 0, 100% 23%, 98.5% 100%, 1.5% 100%, 0 89%);
  box-shadow: 0 0 0 1px var(--amber-hot), 0 10px 40px rgba(242,167,59,0.19);
  transition: transform .18s, filter .18s, box-shadow .18s;
}
.start-btn::after {
  content: ">>"; position: absolute; right: 18px; top: 50%; transform: translateY(-50%);
  font: 21px "Bebas Neue", sans-serif; letter-spacing: 4px; color: rgba(20,14,7,0.55); transition: transform .2s;
}
.start-btn:hover { transform: translateY(-2px); filter: brightness(1.08); box-shadow: 0 0 0 1px var(--amber-hot), 0 16px 50px rgba(242,167,59,0.3); }
.start-btn:hover::after { transform: translate(4px, -50%); }
.start-btn:active { transform: translateY(1px); }
.btn-noise { position: absolute; inset: 0; opacity: .18; background-image: repeating-linear-gradient(110deg, transparent 0 7px, rgba(0,0,0,.5) 7px 8px); pointer-events: none; }
.start-btn-label { position: relative; display: block; font-family: "Bebas Neue", sans-serif; font-size: 31px; letter-spacing: 0.06em; line-height: .92; }
.start-btn-sub { position: relative; display: block; font-size: 8px; font-weight: 600; letter-spacing: .23em; opacity: .62; margin-top: 3px; }
.start-meta { display: flex; align-items: center; gap: 17px; }
.start-meta div { display: flex; flex-direction: column; gap: 1px; }
.start-meta span { font: 25px/1 "Bebas Neue", sans-serif; color: var(--bone); }
.start-meta b { font-size: 7px; font-weight: 600; letter-spacing: .17em; color: rgba(238,225,199,0.42); }
.start-meta i { width: 1px; height: 26px; background: rgba(238,225,199,0.17); }
.how-to {
  display: flex; gap: 22px; margin-top: 29px; padding-top: 18px; width: max-content;
  border-top: 1px solid rgba(238,225,199,0.12);
  opacity: 0; animation: title-in .5s 1s ease forwards;
}
.how-item { display: flex; gap: 8px; align-items: center; }
.how-item > div { display: flex; flex-direction: column; }
.how-item b { font-size: 9px; font-weight: 600; letter-spacing: .17em; color: rgba(238,225,199,0.72); }
.how-item em { font: 8px "Special Elite", serif; color: rgba(238,225,199,0.35); margin-top: 2px; font-style: normal; }
.joy-icon { width: 25px; height: 25px; border: 1px solid rgba(238,225,199,0.35); border-radius: 50%; display: grid; place-items: center; }
.joy-icon i { width: 9px; height: 9px; background: var(--amber); border-radius: 50%; transform: translate(3px,-2px); }
.fire-icon { position: relative; width: 25px; height: 25px; border: 1px solid rgba(238,225,199,0.35); border-radius: 50%; }
.fire-icon::before, .fire-icon::after { content: ""; position: absolute; background: rgba(238,225,199,0.35); }
.fire-icon::before { width: 13px; height: 1px; left: 5px; top: 11px; }
.fire-icon::after { width: 1px; height: 13px; left: 11px; top: 5px; }
.hammer-icon, .trap-icon { width: 25px; height: 25px; display: grid; place-items: center; font-size: 16px; color: var(--amber); border: 1px solid rgba(238,225,199,0.22); }
.start-footer {
  position: absolute; z-index: 5; left: var(--safe-l); right: var(--safe-r); bottom: var(--safe-b);
  display: flex; align-items: flex-end; gap: 14px; max-width: 750px;
  opacity: 0; animation: title-in .5s 1.1s ease forwards;
}
.rating-box { width: 34px; height: 34px; display: grid; place-items: center; background: var(--bone); color: #0a0c13; font: 25px/1 "Bebas Neue", sans-serif; }
.start-footer p { display: flex; flex-direction: column; gap: 2px; margin: 0; }
.start-footer p b { font-size: 8px; font-weight: 600; letter-spacing: .16em; color: rgba(238,225,199,0.5); }
.start-footer p span { font: 8px "Special Elite", serif; color: rgba(238,225,199,0.26); }
.format-tag { margin-left: auto; text-align: right; display: flex; flex-direction: column; }
.format-tag b { font: 18px/1 "Bebas Neue", sans-serif; letter-spacing: .12em; color: rgba(238,225,199,0.7); }
.format-tag span { font-size: 7px; letter-spacing: .21em; color: rgba(238,225,199,0.3); margin-top: 2px; }
.start-tip {
  position: absolute; z-index: 4; right: var(--safe-r); top: 49%; transform: translateY(-50%) rotate(90deg);
  transform-origin: right center; font-size: 8px; letter-spacing: .18em; color: rgba(238,225,199,0.28);
}
.start-tip span { color: var(--amber); }

/* ============ HUD ============ */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud-top {
  position: absolute; top: var(--safe-t); left: var(--safe-l); right: var(--safe-r);
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: start; gap: 20px;
}
.brand-mini { display: flex; align-items: center; gap: 9px; justify-self: start; filter: drop-shadow(0 4px 10px rgba(0,0,0,.4)); }
.brand-mini svg { width: 32px; height: 32px; fill: var(--bone); }
.brand-mini svg circle, .brand-mini svg path:last-child { fill: #090b12; }
.brand-mini div { display: flex; flex-direction: column; }
.brand-mini b { font-family: "Bebas Neue", sans-serif; font-size: 22px; letter-spacing: .07em; line-height: .8; color: var(--bone); }
.brand-mini span { font-size: 6.5px; letter-spacing: .24em; font-weight: 600; color: var(--amber); margin-top: 4px; }
.wave-card { justify-self: center; text-align: center; width: clamp(190px, 24vw, 320px); }
.wave-kicker { display: flex; justify-content: center; align-items: center; gap: 9px; font-size: 8px; font-weight: 600; letter-spacing: .2em; color: rgba(238,225,199,0.55); }
.wave-kicker i { width: 4px; height: 4px; background: var(--blood); transform: rotate(45deg); }
#wave-state { color: var(--amber); }
.wave-title { font: 24px/1 "Bebas Neue", sans-serif; letter-spacing: .12em; margin-top: 3px; color: var(--bone); text-shadow: 0 2px 10px rgba(0,0,0,.7); }
.wave-track { position: relative; height: 3px; margin-top: 6px; background: rgba(238,225,199,0.14); overflow: hidden; }
.wave-track > div { height: 100%; width: 0%; background: linear-gradient(90deg, var(--blood), var(--amber)); box-shadow: 0 0 12px var(--amber); transition: width .28s ease; }
.wave-ticks { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 calc(16.666% - 1px), rgba(7,8,12,0.9) calc(16.666% - 1px) 16.666%); }
.score-cluster { justify-self: end; display: flex; align-items: center; gap: 12px; }
.score-box, .scrap-box { display: flex; flex-direction: column; align-items: flex-end; line-height: 1; }
.score-box span, .scrap-box small { font-size: 6.5px; font-weight: 600; letter-spacing: .23em; color: rgba(238,225,199,0.36); }
.score-box b { font: 25px/1 "Bebas Neue", sans-serif; letter-spacing: .08em; color: var(--bone); margin-top: 3px; }
.scrap-box { position: relative; padding-left: 14px; }
.scrap-box::before { content: ""; position: absolute; left: 0; top: 3px; bottom: 3px; width: 1px; background: rgba(238,225,199,0.16); }
.scrap-icon { position: absolute; left: 12px; bottom: 10px; color: var(--amber); font-size: 10px; }
.scrap-box b { font: 25px/1 "Bebas Neue", sans-serif; color: var(--amber-hot); margin-top: 3px; padding-left: 13px; }
.scrap-box small { color: rgba(238,225,199,0.32); }
.icon-btn { width: 30px; height: 30px; display: grid; place-items: center; border: 1px solid rgba(238,225,199,0.16); pointer-events: auto; opacity: .7; transition: opacity .2s, border-color .2s; }
.icon-btn:hover { opacity: 1; border-color: rgba(238,225,199,0.4); }
.icon-btn svg { width: 15px; fill: none; stroke: var(--bone); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn.muted .sound-on { opacity: .3; }

.hud-left { position: absolute; left: var(--safe-l); top: calc(var(--safe-t) + 57px); display: flex; flex-direction: column; gap: 12px; }
.survivor-card { display: flex; align-items: center; gap: 9px; }
.portrait { width: 50px; height: 57px; flex: none; background: linear-gradient(145deg, #2b2e3a, #151822); border: 1px solid rgba(238,225,199,0.26); box-shadow: 0 5px 20px rgba(0,0,0,.4); position: relative; overflow: hidden; }
.portrait::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, transparent 55%, rgba(215,75,64,0.18)); }
.portrait svg { width: 100%; height: 100%; display: block; }
.survivor-meta { width: 168px; }
.survivor-name { display: flex; justify-content: space-between; align-items: baseline; }
.survivor-name span { font: 19px/1 "Bebas Neue", sans-serif; letter-spacing: .12em; }
.survivor-name em { font: 7px/1 "Oswald", sans-serif; letter-spacing: .16em; font-style: normal; color: var(--amber); }
.health-track { position: relative; height: 10px; margin-top: 5px; background: rgba(5,6,10,0.75); border: 1px solid rgba(238,225,199,0.2); overflow: hidden; clip-path: polygon(0 0, 100% 0, 97% 100%, 0 100%); }
.health-track > div { height: 100%; width: 100%; background: linear-gradient(90deg, #a83731, var(--blood) 60%, #ee7054); transition: width .22s ease; box-shadow: 0 0 12px rgba(215,75,64,0.5); }
.health-track span { position: absolute; right: 5px; top: 0; font: 8px/10px "Oswald", sans-serif; letter-spacing: .07em; color: rgba(255,255,255,0.72); }
.status-row { display: flex; align-items: center; gap: 5px; margin-top: 4px; font-size: 6.5px; font-weight: 600; letter-spacing: .18em; color: rgba(238,225,199,0.37); }
.status-dot { width: 4px; height: 4px; border-radius: 50%; background: #6fc781; box-shadow: 0 0 7px #6fc781; }
.status-row.hurt .status-dot { background: var(--blood); box-shadow: 0 0 7px var(--blood); }
.status-row.hurt { color: #d77b6e; }

.barricade-panel { width: 160px; padding: 9px 10px 8px; background: rgba(6,8,13,0.52); border-left: 2px solid rgba(238,225,199,0.16); backdrop-filter: blur(5px); }
.panel-label { font-size: 6.5px; font-weight: 600; letter-spacing: .23em; color: rgba(238,225,199,0.35); display: block; margin-bottom: 5px; }
.barricade-row { display: flex; align-items: center; gap: 6px; height: 15px; }
.barricade-row i { font: normal 8px "Bebas Neue", sans-serif; letter-spacing: .04em; color: rgba(238,225,199,0.45); width: 8px; }
.mini-bar { flex: 1; height: 3px; background: rgba(238,225,199,0.13); overflow: hidden; }
.mini-bar span { display: block; height: 100%; width: 100%; background: #a9a188; transition: width .2s, background .2s; }
.barricade-row b { width: 24px; text-align: right; font: 8px "Oswald", sans-serif; font-weight: 400; color: rgba(238,225,199,0.5); }
.barricade-row.warn .mini-bar span { background: var(--amber); }
.barricade-row.crit .mini-bar span { background: var(--blood); }
.barricade-row.crit b { color: var(--blood); }

.hud-right { position: absolute; right: var(--safe-r); top: calc(var(--safe-t) + 60px); display: flex; flex-direction: column; align-items: flex-end; gap: 10px; }
.clear-banner, .break-banner { text-align: right; padding: 9px 13px 10px; background: linear-gradient(90deg, transparent, rgba(8,10,16,0.76)); border-right: 2px solid var(--amber); }
.clear-banner span, .break-banner span { font-size: 7px; letter-spacing: .26em; color: var(--amber); font-weight: 600; display: block; }
.clear-banner b { font: 30px/1 "Bebas Neue", sans-serif; letter-spacing: .12em; display: block; color: var(--bone); margin: 2px 0; }
.clear-banner em, .break-banner em { font: normal 7px "Special Elite", serif; color: rgba(238,225,199,0.48); letter-spacing: .06em; }
.break-banner { border-right-color: var(--blood); }
.break-banner b { font: 33px/1 "Bebas Neue", sans-serif; color: var(--bone); display: block; margin: 2px 0; letter-spacing: .08em; }
.break-banner span { color: var(--blood); }

.objective {
  position: absolute; left: 50%; bottom: 30px; transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px; padding: 8px 15px 8px 10px;
  background: rgba(7,9,14,0.64); border: 1px solid rgba(238,225,199,0.13); backdrop-filter: blur(6px);
  transition: opacity .4s, transform .4s;
}
.objective.fade { opacity: 0; transform: translate(-50%, 8px); }
.objective-icon { color: var(--amber); font-size: 12px; }
.objective div { display: flex; flex-direction: column; }
.objective b { font-size: 8px; font-weight: 600; letter-spacing: .2em; color: var(--bone); }
.objective em { font: 8px "Special Elite", serif; color: rgba(238,225,199,0.42); margin-top: 2px; font-style: normal; }

.toast-stack { position: absolute; left: 50%; top: 19%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 6px; }
.toast {
  padding: 6px 14px; background: rgba(8,10,16,0.82); border-left: 2px solid var(--amber);
  font-size: 10px; font-weight: 600; letter-spacing: .14em; color: var(--bone); white-space: nowrap;
  animation: toast-in .3s ease, toast-out .35s 1.65s ease forwards; backdrop-filter: blur(4px);
}
.toast.bad { border-left-color: var(--blood); color: #ffb4a9; }
.toast.good { border-left-color: var(--teal); }
@keyframes toast-in { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: translateY(0); } }
@keyframes toast-out { to { opacity: 0; transform: translateY(-5px); } }

.hud-bottom { position: absolute; left: var(--safe-l); right: var(--safe-r); bottom: var(--safe-b); display: flex; align-items: flex-end; justify-content: space-between; }
.ammo-cluster { width: 190px; }
.weapon-name { display: flex; align-items: baseline; gap: 7px; margin-bottom: 5px; }
.weapon-name span { font: 18px/1 "Bebas Neue", sans-serif; letter-spacing: .1em; color: var(--bone); }
.weapon-name em { font: 6.5px "Oswald", sans-serif; letter-spacing: .17em; color: rgba(238,225,199,0.34); font-style: normal; }
.shells { display: flex; gap: 4px; height: 15px; align-items: flex-end; }
.shell { position: relative; width: 7px; height: 15px; background: linear-gradient(90deg, #6e241e, #d85939 48%, #8c2d22 100%); border-radius: 1px 1px 0 0; box-shadow: 0 0 0 1px rgba(0,0,0,.45); transition: opacity .12s, transform .12s; }
.shell::before { content: ""; position: absolute; bottom: 0; left: 0; right: 0; height: 4px; background: linear-gradient(90deg, #b99551, #f2d18c, #8d6a37); }
.shell.empty { opacity: .16; transform: translateY(2px); }
.reload-label { margin-top: 3px; font-size: 7px; letter-spacing: .24em; color: var(--amber); animation: blink .7s infinite alternate; }
@keyframes blink { from { opacity: .35; } to { opacity: 1; } }
.touch-tip { position: absolute; left: 50%; bottom: 10px; transform: translateX(-50%); font-size: 7px; font-weight: 600; letter-spacing: .14em; color: rgba(238,225,199,0.31); white-space: nowrap; }
.touch-tip i { display: inline-block; width: 2px; height: 2px; border-radius: 50%; background: rgba(238,225,199,0.3); margin: 0 8px; vertical-align: middle; }
.tip-mouse { padding: 3px 5px; border: 1px solid rgba(238,225,199,0.17); color: rgba(238,225,199,0.58); }

/* Touch controls */
.joystick-zone { position: absolute; left: calc(var(--safe-l) + 10px); bottom: calc(var(--safe-b) + 36px); width: 140px; height: 140px; display: none; pointer-events: auto; touch-action: none; }
.joystick-ring { position: absolute; inset: 8px; border: 1px solid rgba(238,225,199,0.12); border-radius: 50%; box-shadow: 0 0 30px rgba(0,0,0,.3); }
.joystick-base {
  position: absolute; left: 50%; top: 50%; width: 112px; height: 112px; transform: translate(-50%, -50%);
  border-radius: 50%; border: 1px solid rgba(238,225,199,0.32);
  background: radial-gradient(circle at 42% 35%, rgba(238,225,199,0.12), rgba(8,10,16,0.36) 60%);
  box-shadow: inset 0 0 24px rgba(0,0,0,0.5);
}
.joystick-base::before { content: ""; position: absolute; inset: 13px; border-radius: 50%; border: 1px dashed rgba(238,225,199,0.14); }
.joystick-knob { position: absolute; left: 50%; top: 50%; width: 52px; height: 52px; margin: -26px 0 0 -26px; border-radius: 50%; background: radial-gradient(circle at 38% 32%, #e7d9bc, #91846d 55%, #524b40); border: 1px solid rgba(255,255,255,.3); box-shadow: 0 6px 16px rgba(0,0,0,.55), inset 0 -4px 8px rgba(0,0,0,.35); pointer-events: none; }
.joystick-knob span { position: absolute; inset: 18px; border-radius: 50%; border: 1px solid rgba(20,18,16,.5); }
.joystick-label { position: absolute; left: 50%; bottom: 0; transform: translateX(-50%); font-size: 6px; font-weight: 600; letter-spacing: .24em; color: rgba(238,225,199,0.34); }
.action-zone { display: none; align-items: flex-end; gap: 11px; pointer-events: auto; position: relative; }
.action-btn { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; pointer-events: auto; touch-action: none; -webkit-tap-highlight-color: transparent; }
.action-btn.secondary {
  width: 62px; height: 62px; border: 1px solid rgba(238,225,199,0.3); border-radius: 50%;
  background: radial-gradient(circle at 42% 32%, rgba(238,225,199,0.16), rgba(8,10,16,0.64) 65%);
  box-shadow: 0 6px 18px rgba(0,0,0,.4); backdrop-filter: blur(3px);
  transition: transform .08s, background .15s, border-color .15s;
}
.action-btn.secondary:active, .action-btn.secondary.armed { transform: scale(.94); background: rgba(242,167,59,0.2); border-color: var(--amber); }
.action-btn .btn-glyph { width: 24px; height: 24px; display: grid; place-items: center; color: var(--bone); }
.action-btn .btn-glyph svg { width: 100%; height: 100%; }
.action-btn.secondary b { font-size: 7px; letter-spacing: .12em; font-weight: 600; margin-top: 1px; color: rgba(238,225,199,0.72); }
.action-btn.secondary em { font-style: normal; font-size: 6px; color: var(--amber); letter-spacing: .06em; margin-top: 1px; }
.scrap-mini { font-style: normal; color: var(--amber); }
.key-hint { display: none; }
.action-btn.fire {
  width: 96px; height: 96px; border-radius: 50%;
  background: radial-gradient(circle at 40% 30%, rgba(255, 115, 73, 0.98), #a92e26 52%, #551814 100%);
  border: 2px solid rgba(255, 188, 124, 0.76);
  box-shadow: 0 8px 28px rgba(138, 24, 17, 0.5), inset 0 0 22px rgba(255, 146, 79, 0.35), 0 0 0 7px rgba(215,75,64,0.1);
  color: #fff0dc; transition: transform .07s, filter .12s;
}
.action-btn.fire:active, .action-btn.fire.firing { transform: scale(.93); filter: brightness(1.25); }
.action-btn.fire .btn-glyph { width: 35px; height: 35px; color: #ffe7c5; filter: drop-shadow(0 0 7px rgba(255,210,140,.7)); }
.action-btn.fire b { font-family: "Bebas Neue", sans-serif; font-size: 17px; font-weight: 400; letter-spacing: .1em; margin-top: -1px; }
.fire-ring { position: absolute; inset: -9px; border: 1px solid rgba(238,225,199,0.22); border-radius: 50%; }
.fire-ring::before { content: ""; position: absolute; inset: 5px; border: 1px dashed rgba(255,220,170,0.16); border-radius: 50%; animation: spin 22s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.target-lock { position: absolute; width: 36px; height: 36px; transform: translate(-50%, -50%); z-index: 9; pointer-events: none; transition: opacity .08s; }
.target-lock i { position: absolute; width: 9px; height: 9px; border-color: rgba(238,225,199,0.8); border-style: solid; }
.target-lock i:nth-child(1) { left: 0; top: 0; border-width: 1px 0 0 1px; }
.target-lock i:nth-child(2) { right: 0; top: 0; border-width: 1px 1px 0 0; }
.target-lock i:nth-child(3) { left: 0; bottom: 0; border-width: 0 0 1px 1px; }
.target-lock i:nth-child(4) { right: 0; bottom: 0; border-width: 0 1px 1px 0; }
.target-lock span { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); font: 8px "Bebas Neue", sans-serif; color: var(--blood); }

.low-health-vignette { z-index: 7; opacity: 0; background: radial-gradient(ellipse at center, transparent 40%, rgba(110, 10, 12, 0.58) 100%); animation: heart 1.25s ease-in-out infinite; transition: opacity .4s; }
.low-health-vignette.on { opacity: 1; }
@keyframes heart { 0%,100% { opacity: .45; } 50% { opacity: .9; } }

/* ============ END SCREEN ============ */
.end-screen { background: radial-gradient(ellipse at 50% 38%, rgba(8,10,16,.18), rgba(4,5,9,.94)); display: flex; align-items: center; justify-content: center; padding: 20px; }
.end-screen::before { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(115deg, transparent 0 80px, rgba(215,75,64,0.06) 80px 81px); }
.end-stamp {
  position: absolute; top: 8%; left: 50%; transform: translateX(-50%) rotate(-4deg);
  font-family: "Bebas Neue", sans-serif; font-size: clamp(60px, 10vw, 130px); line-height: .8;
  color: transparent; -webkit-text-stroke: 2px rgba(215,75,64,0.48); letter-spacing: .1em; white-space: nowrap;
  opacity: .75; pointer-events: none;
}
.end-panel { position: relative; width: min(500px, 100%); text-align: center; padding: 37px 35px 30px; background: rgba(8, 10, 16, 0.92); border: 1px solid rgba(238,225,199,0.24); box-shadow: 0 30px 100px rgba(0,0,0,.75); }
