  return {
    root, barriers, animated, moonLight,
    update(t, dt) {
      dust.rotation.y = t * .006;
      dust.position.y = Math.sin(t * .12) * .08;
      stars.rotation.y = t * .0015;
      for (const s of animated.signs) {
        const flicker = .9 + Math.sin(t * s.rate + s.seed) * .07 + (Math.sin(t * 13.7 + s.seed) > .96 ? -.3 : 0);
        if (s.mat && s.mat.opacity !== undefined) s.mat.opacity = Math.min(1, .78 + flicker * .2);
        if (s.light) s.light.intensity = s.base * flicker;
      }
      for (const b of animated.bulbs) {
        const glow = .65 + Math.sin(t * 2.2 + b.phase) * .2;
        b.mesh.material.opacity = glow;
      }
      if (animated.fire) {
        const f = animated.fire;
        const flick = .82 + Math.sin(t * 13) * .1 + Math.sin(t * 23.7) * .07;
        f.flame.scale.y = flick; f.flame.scale.x = .88 + Math.sin(t * 17) * .08;
        f.flame2.scale.y = .9 + Math.sin(t * 20 + 2) * .12;
        f.light.intensity = f.base * flick;
      }
      for (const s of animated.smoke) {
        const p = (t * .12 + s.userData.phase) % 1;
        s.position.y = s.userData.baseY + p * 3.2;
        s.material.opacity = .23 * (1 - p);
        s.scale.setScalar(s.userData.baseScale * (1 + p * 1.4));
      }
      for (let i = 0; i < barriers.length; i++) {
        const b = barriers[i];
        if (b.shake > 0) {
          b.shake = Math.max(0, b.shake - dt * 2.4);
          b.group.rotation.z = Math.sin(t * 54 + i) * b.shake * .012;
          b.group.position.y = Math.sin(t * 40) * b.shake * .025;
        }
        if (b.beaconMat) {
          const ratio = b.hp / b.maxHp;
          b.beaconMat.color.setHex(ratio > .55 ? 0x7ee39e : ratio > .22 ? 0xffb04c : 0xff5246);
        }
      }
    },
  };
}

/* Tiny synthesized soundscape: rockabilly loop, shotgun, groans, creaks. */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.noise = null;
    this.muted = false;
    this.started = false;
    this.step = 0;
    this.nextNote = 0;
    this.musicOn = false;
    this.intensity = 0;
  }

  async init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') await this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.72;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -18;
    comp.knee.value = 16;
    comp.ratio.value = 5;
    comp.attack.value = 0.003;
    comp.release.value = 0.24;
    this.master.connect(comp).connect(this.ctx.destination);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.14;
    this.musicGain.connect(this.master);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.72;
    this.sfxGain.connect(this.master);

    const len = this.ctx.sampleRate * 2;
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noise = buffer;

    this.startWind();
    this.started = true;
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(muted ? 0 : 0.72, this.ctx.currentTime + 0.12);
    }
  }

  startWind() {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise; src.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass'; filter.frequency.value = 340; filter.Q.value = 0.6;
    const gain = this.ctx.createGain(); gain.gain.value = 0.028;
    const lfo = this.ctx.createOscillator(); lfo.frequency.value = 0.07;
    const lfoGain = this.ctx.createGain(); lfoGain.gain.value = 0.012;
    lfo.connect(lfoGain).connect(gain.gain);
    src.connect(filter).connect(gain).connect(this.master);
    src.start(); lfo.start();
    this.wind = { src, gain, filter };
  }

  noiseBurst(duration = 0.22, volume = 0.6, frequency = 900, q = 0.8, type = 'lowpass') {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type; filter.frequency.setValueAtTime(frequency, t);
    filter.frequency.exponentialRampToValueAtTime(Math.max(100, frequency * 0.28), t + duration);
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(volume, t);
    gain.gain.exponentialRampToValueAtTime(0.001, t + duration);
    src.connect(filter).connect(gain).connect(this.sfxGain);
    src.start(t); src.stop(t + duration);
  }

  tone(freq, duration, volume = 0.1, type = 'sine', slide = null, delay = 0) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(slide, t + duration);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(volume, t + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    o.connect(g).connect(this.sfxGain);
    o.start(t); o.stop(t + duration + 0.02);
  }

  shot() {
    if (!this.ctx) return;
    this.noiseBurst(0.3, 0.75, 2100, 1.1);
    this.noiseBurst(0.14, 0.35, 5600, 0.8, 'highpass');
    this.tone(92, 0.2, 0.3, 'sine', 38);
    this.tone(42, 0.3, 0.22, 'triangle', 28);
  }
  empty() { this.tone(540, 0.06, 0.1, 'square', 320); this.tone(210, 0.06, 0.06, 'square', 160, 0.04); }
  reload() {
    this.tone(320, 0.05, 0.1, 'square', 240);
    this.tone(640, 0.04, 0.08, 'square', 480, 0.36);
    this.tone(410, 0.06, 0.09, 'square', 280, 0.78);
  }
  hit() { this.noiseBurst(0.08, 0.22, 1500, 0.6); this.tone(130, 0.1, 0.12, 'triangle', 60); }
  crit() { this.tone(880, 0.06, 0.08, 'square', 1400); this.tone(1600, 0.05, 0.05, 'sine', 1900, 0.04); }
  splat() { this.noiseBurst(0.22, 0.28, 700, 0.7); this.tone(75, 0.25, 0.14, 'sawtooth', 32); }
  growl() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    o.type = 'sawtooth'; o.frequency.setValueAtTime(56 + Math.random() * 16, t);
    o.frequency.exponentialRampToValueAtTime(38, t + 0.55);
    f.type = 'lowpass'; f.frequency.value = 260;
    g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.055, t + 0.08); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.6);
    o.connect(f).connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 0.62);
  }
  hurt() { this.noiseBurst(0.18, 0.4, 650, 0.6); this.tone(180, 0.22, 0.16, 'sawtooth', 70); }
  repair() {
    this.tone(310, 0.12, 0.13, 'square', 620);
    this.tone(460, 0.18, 0.1, 'triangle', 220, 0.09);
    this.noiseBurst(0.1, 0.1, 2400, 1.4, 'bandpass');
  }
  trap() {
    this.noiseBurst(0.08, 0.32, 3200, 0.9, 'bandpass');
    this.tone(900, 0.18, 0.13, 'square', 120);
    this.tone(70, 0.3, 0.16, 'triangle', 35, 0.04);
  }
  build() { this.noiseBurst(0.12, 0.2, 1600, 0.4); this.tone(190, 0.08, 0.1, 'square', 110); }
  reloadDone() { this.tone(720, 0.06, 0.1, 'square', 920); this.tone(380, 0.05, 0.06, 'square', 300, 0.08); }
  ui() { this.tone(620, 0.04, 0.055, 'square', 820); }
  levelUp() {
    [392, 523, 659, 784].forEach((f, i) => this.tone(f, 0.18, 0.065, 'triangle', null, i * 0.08));
  }
  horn() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    [138, 174, 207].forEach((f, i) => {
      const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
      o.type = i === 1 ? 'sawtooth' : 'square'; o.frequency.value = f;
      g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.055, t + 0.15); g.gain.exponentialRampToValueAtTime(0.0001, t + 1.15);
      o.connect(g).connect(this.sfxGain); o.start(t); o.stop(t + 1.2);
    });
  }
  victory() {
    [262, 330, 392, 523, 659].forEach((f, i) => this.tone(f, 0.5, 0.08, 'triangle', null, i * 0.12));
    this.noiseBurst(0.7, 0.05, 3000, 0.4);
  }
  death() {
    [196, 165, 131, 98].forEach((f, i) => this.tone(f, 0.5, 0.1, 'sawtooth', f * .92, i * .16));
    this.noiseBurst(1.2, 0.1, 500, .4);
  }

  startMusic() {
    if (!this.ctx || this.musicOn) return;
    this.musicOn = true;
    this.step = 0;
    this.nextNote = this.ctx.currentTime + 0.1;
    this.musicGain.gain.setTargetAtTime(0.13, this.ctx.currentTime, .4);
  }
  stopMusic() {
    this.musicOn = false;
    if (this.musicGain) this.musicGain.gain.setTargetAtTime(0.0001, this.ctx.currentTime, .4);
  }

  update(intensity = 0) {
    if (!this.ctx || !this.musicOn) return;
    this.intensity = intensity;
    const bpm = 104 + intensity * 18;
    const stepDur = 60 / bpm / 2;
    while (this.nextNote < this.ctx.currentTime + 0.16) {
      this.playStep(this.step, this.nextNote, bpm);
      this.nextNote += stepDur;
      this.step = (this.step + 1) % 32;
    }
  }

  playStep(step, time, bpm) {
    const ctx = this.ctx;
    const bar = Math.floor(step / 8);
    const beat = step % 8;
    const bassRoots = [55, 55, 43.65, 49]; // A, A, F, G
    const root = bassRoots[bar % 4];

    // kick on 1 & 3 of each 4/4 bar
    if (beat === 0 || beat === 4) this.musicKick(time, beat === 0 ? .16 : .1);
    // brush snare backbeat
    if (beat === 2 || beat === 6) this.musicSnare(time);
    // hats
    if (step % 2 === 1) this.musicHat(time, .012);
    // walking bass
    const pattern = [0, 0, 12, 7, 0, 0, -5, 7];
    const freq = root * Math.pow(2, pattern[beat] / 12);
    if (beat % 2 === 0 || Math.random() > .45) this.musicBass(freq, time, beat === 0 ? .11 : .075);
    // twangy guitar on upbeats
    if (beat === 1 || beat === 5) this.musicTwang(root * 4, time);
    if (bar === 3 && beat === 7) this.musicTwang(root * 6, time + .02);
    // tambourine/shaker
    this.musicShaker(time, .009);
  }

  musicKick(time, vol) {
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
    o.type = 'sine'; o.frequency.setValueAtTime(105, time); o.frequency.exponentialRampToValueAtTime(42, time + .14);
    g.gain.setValueAtTime(vol, time); g.gain.exponentialRampToValueAtTime(.0001, time + .18);
    o.connect(g).connect(this.musicGain); o.start(time); o.stop(time + .2);
  }
  musicSnare(time) {
    const src = this.ctx.createBufferSource(); src.buffer = this.noise;
    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 1600; f.Q.value = .7;
    const g = this.ctx.createGain(); g.gain.setValueAtTime(.055, time); g.gain.exponentialRampToValueAtTime(.0001, time + .11);
    src.connect(f).connect(g).connect(this.musicGain); src.start(time); src.stop(time + .12);
  }
  musicHat(time, vol) {
    const src = this.ctx.createBufferSource(); src.buffer = this.noise;
    const f = this.ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 6100;
    const g = this.ctx.createGain(); g.gain.setValueAtTime(vol, time); g.gain.exponentialRampToValueAtTime(.0001, time + .035);
    src.connect(f).connect(g).connect(this.musicGain); src.start(time); src.stop(time + .04);
  }
  musicShaker(time, vol) {
    if (Math.random() > .7) return;
    const src = this.ctx.createBufferSource(); src.buffer = this.noise;
    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = 7300; f.Q.value = 1.2;
    const g = this.ctx.createGain(); g.gain.setValueAtTime(vol, time); g.gain.exponentialRampToValueAtTime(.0001, time + .06);
    src.connect(f).connect(g).connect(this.musicGain); src.start(time); src.stop(time + .07);
  }
  musicBass(freq, time, vol) {
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 500;
    o.type = 'triangle'; o.frequency.value = freq;
    g.gain.setValueAtTime(.0001, time); g.gain.linearRampToValueAtTime(vol, time + .015); g.gain.exponentialRampToValueAtTime(.0001, time + .15);
    o.connect(f).connect(g).connect(this.musicGain); o.start(time); o.stop(time + .17);
  }
  musicTwang(freq, time) {
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.setValueAtTime(2400, time); f.frequency.exponentialRampToValueAtTime(800, time + .18);
    o.type = 'sawtooth'; o.frequency.setValueAtTime(freq, time); o.frequency.exponentialRampToValueAtTime(freq * .995, time + .2);
    g.gain.setValueAtTime(.022, time); g.gain.exponentialRampToValueAtTime(.0001, time + .22);
    o.connect(f).connect(g).connect(this.musicGain); o.start(time); o.stop(time + .24);
  }
}

import * as THREE from 'three';

const SKIN = [0xd8b18b, 0xa87758, 0x7d513c, 0xc29470, 0x875e45];
const SHIRTS = [0x626b55, 0x7d3d37, 0x4c5c74, 0x8d7854, 0x5a3e58, 0x7e7a69, 0x385957];
const PANTS = [0x33363f, 0x4b4038, 0x2d3430, 0x554a40, 0x3c3a4c];

function flat(color, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness: 0.82, metalness: 0.03, flatShading: true, ...extra });
}

const blobTex = (() => {
  if (typeof document === 'undefined') return null;
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d');
  const grd = g.createRadialGradient(32, 32, 2, 32, 32, 31);
  grd.addColorStop(0, 'rgba(0,0,0,.56)'); grd.addColorStop(.65, 'rgba(0,0,0,.28)'); grd.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grd; g.fillRect(0, 0, 64, 64);
  const t = new THREE.CanvasTexture(c);
  return t;
})();

function blob(shadowScale = 1) {
  const m = new THREE.Mesh(
    new THREE.PlaneGeometry(shadowScale, shadowScale),
    new THREE.MeshBasicMaterial({ map: blobTex, transparent: true, depthWrite: false, opacity: .75 })
  );
  m.rotation.x = -Math.PI / 2;
  m.position.y = .015;
  return m;
}

function meshBox(w, h, d, mat, x, y, z) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true; m.receiveShadow = true;
  return m;
}

export function createSurvivor() {
  const root = new THREE.Group();
  root.name = 'survivor';
  const body = new THREE.Group();
  root.add(body);
  root.add(blob(1.4));

  const jacket = flat(0x7f3b34, { roughness: .9 });
  const jacketDark = flat(0x542a27, { roughness: .92 });
  const shirt = flat(0xd4c2a0, { roughness: .95 });
  const jeans = flat(0x35414e, { roughness: .92 });
  const boots = flat(0x2d211d, { roughness: .76 });
  const skin = flat(0xc6956e, { roughness: .9 });
  const hair = flat(0x241d1b, { roughness: .9 });
  const metal = flat(0x595a5e, { roughness: .35, metalness: .7 });

  const leftLeg = new THREE.Group();
  leftLeg.position.set(-0.17, .92, 0);
  leftLeg.add(meshBox(.26, .78, .28, jeans, 0, -.38, 0));
  leftLeg.add(meshBox(.3, .2, .42, boots, 0, -.84, .05));
  leftLeg.add(meshBox(.29, .35, .3, jacketDark, 0, -.66, -.01));
  body.add(leftLeg);

  const rightLeg = leftLeg.clone();
  rightLeg.position.x = .17;
  body.add(rightLeg);

  const torso = meshBox(.64, .7, .38, jacket, 0, 1.27, 0);
  body.add(torso);
  // shirt V
  const vShirt = meshBox(.26, .32, .02, shirt, 0, 1.42, .2, false);
  vShirt.rotation.z = 0; body.add(vShirt);
  // collar
  for (const s of [-1, 1]) {
    const c = meshBox(.22, .1, .13, jacketDark, .11 * s, 1.61, .15);
    c.rotation.z = s * .4; body.add(c);
  }
  // belt
  body.add(meshBox(.66, .1, .4, boots, 0, .92, 0));
  body.add(meshBox(.12, .12, .04, metal, 0, .92, .22, false));
  // neck
  body.add(meshBox(.2, .16, .2, skin, 0, 1.68, 0));
  // head
  const head = new THREE.Mesh(new THREE.CapsuleGeometry(.19, .16, 4, 8), skin);
  head.position.set(0, 1.88, .02); head.castShadow = true; body.add(head);
  // nose
  const nose = new THREE.Mesh(new THREE.ConeGeometry(.05, .12, 4), skin);
  nose.rotation.x = Math.PI / 2; nose.position.set(0, 1.87, .22); body.add(nose);
  // eyes
  for (const x of [-.075, .075]) body.add(meshBox(.045, .045, .02, flat(0x171512), x, 1.92, .2, false));
  // brow
  body.add(meshBox(.27, .035, .025, hair, 0, 1.965, .2, false));
  // hair cap
  const capBrim = meshBox(.36, .055, .24, flat(0x8b6f45), 0, 2.035, .16, false);
  const capTop = new THREE.Mesh(new THREE.SphereGeometry(.205, 8, 5, 0, Math.PI * 2, 0, Math.PI * .48), flat(0x9f8252));
  capTop.position.set(0, 2.02, 0); capTop.scale.z = 1.1; capTop.castShadow = true;
  body.add(capTop); body.add(capBrim);
  const hairSide = meshBox(.38, .16, .08, hair, 0, 1.92, -.17, false); body.add(hairSide);
  // bandana
  body.add(meshBox(.54, .12, .4, flat(0x9c3931), 0, 1.59, 0));

  const leftArm = new THREE.Group();
  leftArm.position.set(-.4, 1.55, 0);
  leftArm.add(meshBox(.18, .5, .2, jacket, 0, -.23, 0));
  leftArm.add(meshBox(.16, .38, .18, jacketDark, 0, -.62, .03));
  leftArm.add(meshBox(.14, .16, .16, skin, 0, -.86, .05));
  body.add(leftArm);

  const rightArm = new THREE.Group();
  rightArm.position.set(.4, 1.55, 0);
  rightArm.add(meshBox(.18, .5, .2, jacket, 0, -.23, 0));
  rightArm.add(meshBox(.16, .38, .18, jacketDark, 0, -.62, .03));
  rightArm.add(meshBox(.14, .16, .16, skin, 0, -.86, .05));
  body.add(rightArm);

  // shotgun, held at hip / chest
  const gun = new THREE.Group();
  gun.position.set(.14, 1.34, .27);
  const stock = meshBox(.12, .16, .45, flat(0x56392b), 0, -.04, -.38);
  stock.rotation.x = -.08; gun.add(stock);
  gun.add(meshBox(.1, .1, .95, flat(0x383a3d, { metalness: .8, roughness: .32 }), 0, .03, .28));
  gun.add(meshBox(.09, .08, .88, flat(0x54575a, { metalness: .75, roughness: .28 }), 0, .11, .3));
  gun.add(meshBox(.17, .16, .2, flat(0x4b2f23), 0, -.05, -.05));
  gun.add(meshBox(.12, .06, .18, flat(0x6b4a37), 0, -.17, .04));
  const muzzle = new THREE.Object3D(); muzzle.position.set(0, .06, .75); gun.add(muzzle);
  // muzzle flash
  const flashMat = new THREE.MeshBasicMaterial({ color: 0xffd38a, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, toneMapped: false });
  const flash = new THREE.Group();
  const flashCore = new THREE.Mesh(new THREE.ConeGeometry(.16, .68, 5), flashMat);
  flashCore.rotation.x = -Math.PI / 2; flashCore.position.z = .3; flash.add(flashCore);
  const flashSide = new THREE.Mesh(new THREE.ConeGeometry(.1, .42, 4), flashMat);
  flashSide.rotation.z = Math.PI / 2; flashSide.position.set(.2, 0, .08); flash.add(flashSide);
  const flashSide2 = flashSide.clone(); flashSide2.rotation.z = -Math.PI / 2; flashSide2.position.x = -.2; flash.add(flashSide2);
  const flashLight = new THREE.PointLight(0xffa447, 0, 7, 2);
  flash.add(flashLight);
  flash.position.set(0, .06, .75); flash.visible = false;
  gun.add(flash);
  body.add(gun);

  // ammo bandolier
  const band = meshBox(.56, .12, .41, flat(0x674232), 0, 1.28, 0);
  band.rotation.z = .5; body.add(band);
  for (let i = 0; i < 5; i++) body.add(meshBox(.055, .14, .03, flat(0xb58a52), -.22 + i * .11, 1.28 + (i - 2) * .105, .22, false));

  const state = { root, body, leftLeg, rightLeg, leftArm, rightArm, gun, muzzle, flash, flashMat, flashLight, aim: 0, recoil: 0 };

  root.userData = state;
  return state;
}

export function animateSurvivor(p, t, speed, dt) {
  const s = Math.min(1, speed);
  const walk = Math.sin(t * 10.5) * .58 * s;
  const bob = Math.abs(Math.sin(t * 10.5)) * .045 * s;
  p.leftLeg.rotation.x = walk;
  p.rightLeg.rotation.x = -walk;
  p.leftArm.rotation.x = -walk * .62 + .08;
  p.rightArm.rotation.x = walk * .35 - .3;
  p.leftArm.rotation.z = .06;
  p.rightArm.rotation.z = -.16;
  p.body.position.y = bob + Math.sin(t * 1.8) * .012;
  p.body.rotation.z = Math.sin(t * 10.5) * .02 * s;
  p.body.rotation.x = s * .035;
  p.gun.rotation.x = -.05 - p.recoil * .16;
  p.gun.position.z = .27 - p.recoil * .1;
  if (p.recoil > 0) p.recoil = Math.max(0, p.recoil - dt * 7.5);
  p.flash.visible = p.flashMat.opacity > .02;
}

export function flashMuzzle(p) {
  p.recoil = 1;
  p.flashMat.opacity = 1;
  p.flash.rotation.z = Math.random() * Math.PI * 2;
  p.flash.scale.setScalar(.8 + Math.random() * .55);
  p.flashLight.intensity = 45;
}
export function updateMuzzle(p, dt) {
  if (p.flashMat.opacity > 0) {
    p.flashMat.opacity = Math.max(0, p.flashMat.opacity - dt * 13);
    p.flashLight.intensity = Math.max(0, p.flashLight.intensity - dt * 500);
  }
}

export function createZombie() {
  const root = new THREE.Group();
  const skin = flat(SKIN[Math.floor(Math.random() * SKIN.length)], { roughness: .96 });
  const shirt = flat(SHIRTS[Math.floor(Math.random() * SHIRTS.length)], { roughness: .94 });
  const pants = flat(PANTS[Math.floor(Math.random() * PANTS.length)], { roughness: .95 });
  const shoe = flat(0x27231f, { roughness: .9 });
  const eyeMat = new THREE.MeshBasicMaterial({ color: Math.random() > .35 ? 0xffa64a : 0xd9ff8a, toneMapped: false });
  const mouthMat = flat(0x3a1314);
  const accent = flat([0x7d2c29, 0x2c4b4a, 0x5b4b2d, 0x3e3b5b][Math.floor(Math.random() * 4)]);

  const body = new THREE.Group();
  root.add(body);
  root.add(blob(1.25));

  const legL = new THREE.Group(); legL.position.set(-.16, .83, 0);
  legL.add(meshBox(.24, .68, .27, pants, 0, -.33, 0));
  legL.add(meshBox(.27, .16, .37, shoe, 0, -.73, .05));
  body.add(legL);
  const legR = legL.clone(); legR.position.x = .16; body.add(legR);

  const torso = meshBox(.58, .72, .36, shirt, 0, 1.17, 0);
  torso.rotation.z = (Math.random() - .5) * .1;
  body.add(torso);
  // shirt tear
  body.add(meshBox(.18, .26, .02, skin, .08, 1.06, .19, false));
  if (Math.random() > .5) body.add(meshBox(.52, .14, .38, accent, 0, .9, 0));
  // shoulders
  body.add(meshBox(.72, .14, .38, shirt, 0, 1.48, 0));

  const armL = new THREE.Group(); armL.position.set(-.38, 1.42, 0);
  armL.add(meshBox(.16, .55, .18, shirt, 0, -.24, 0));
  armL.add(meshBox(.13, .42, .15, skin, 0, -.66, .02));
  armL.add(meshBox(.12, .14, .15, skin, 0, -.9, .03));
  body.add(armL);
  const armR = armL.clone(); armR.position.x = .38; body.add(armR);

  const neck = meshBox(.19, .17, .19, skin, 0, 1.58, 0); body.add(neck);
  const head = new THREE.Group(); head.position.set(0, 1.75, .01);
  const skull = new THREE.Mesh(new THREE.CapsuleGeometry(.2, .12, 4, 8), skin);
  skull.castShadow = true; skull.rotation.z = (Math.random() - .5) * .18; head.add(skull);
  // jaw
  const jaw = meshBox(.21, .12, .18, skin, 0, -.1, .04); head.add(jaw);
  head.add(meshBox(.18, .06, .03, mouthMat, 0, -.05, .18, false));
  for (const x of [-.07, .07]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(.032, 5, 4), eyeMat);
    eye.position.set(x, .045, .185); head.add(eye);
  }
  // brow cavity
  head.add(meshBox(.3, .06, .06, flat(0x4a2b28), 0, .085, .16, false));
  // hat / hair
  const style = Math.random();
  if (style > .72) {
    const brim = meshBox(.47, .045, .42, accent, 0, .16, 0); head.add(brim);
    head.add(meshBox(.3, .18, .3, accent, 0, .27, 0));
  } else if (style > .42) {
    const cap = new THREE.Mesh(new THREE.SphereGeometry(.215, 7, 4, 0, Math.PI * 2, 0, Math.PI * .52), flat(0x3e3a32));
    cap.position.y = .07; head.add(cap);
    head.add(meshBox(.31, .04, .22, flat(0x302d28), 0, .1, .14, false));
  } else {
    for (let i = 0; i < 5; i++) {
      const h = meshBox(.1, .12, .08, flat(0x2b211d), -.18 + i * .09, .13 + Math.random() * .04, -.02, false);
      h.rotation.z = (Math.random() - .5) * .7; head.add(h);
    }
  }
  body.add(head);

  // wounds / blood
  const blood = flat(0x5d1e1c, { roughness: 1 });
  body.add(meshBox(.16, .2, .02, blood, -.17, 1.21, .19, false));
  body.add(meshBox(.12, .12, .02, blood, .22, 1.02, .19, false));

  const hitFlash = new THREE.Mesh(new THREE.BoxGeometry(.8, 1.9, .6), new THREE.MeshBasicMaterial({ color: 0xfff1d0, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending }));
  hitFlash.position.y = 1; body.add(hitFlash);

  root.scale.setScalar(.9 + Math.random() * .24);
  const parts = { root, body, legL, legR, armL, armR, head, hitFlash, eyeMat, style };
  root.userData = parts;
  return parts;
}

export function animateZombie(z, t, speed, state = 'walk') {
  const s = Math.min(1.4, speed);
  const phase = t * (7.2 + s) + z.phase;
  const limp = Math.sin(phase) * .58 * s;
  z.legL.rotation.x = limp;
  z.legR.rotation.x = -limp;
  z.body.position.y = Math.abs(Math.sin(phase)) * .045 * s;
  z.body.rotation.z = Math.sin(phase) * .055 * s;
  z.armL.rotation.x = -1.1 + Math.sin(phase + .4) * .17;
  z.armR.rotation.x = -1.02 + Math.sin(phase + 1.4) * .2;
  z.armL.rotation.z = .12;
  z.armR.rotation.z = -.1;
  z.head.rotation.z = Math.sin(phase * .7) * .11;
  z.head.rotation.y = Math.sin(phase * .4) * .1;
  if (state === 'attack') {
    z.armL.rotation.x = -1.5 + Math.sin(t * 9) * .6;
    z.armR.rotation.x = -1.4 + Math.sin(t * 9 + 2) * .55;
    z.body.rotation.x = .18 + Math.sin(t * 9) * .07;
  } else {
    z.body.rotation.x = .03;
  }
  if (z.hitFlash.material.opacity > 0) z.hitFlash.material.opacity = Math.max(0, z.hitFlash.material.opacity - .13);
}

export function hitZombie(z) {
  z.hitFlash.material.opacity = .22;
}

import * as THREE from 'three';

const MAX = 520;

class PointPool {
  constructor(scene, { size = .09, additive = true, opacity = .9, gravity = 9 } = {}) {
    this.scene = scene;
    this.gravity = gravity;
    this.pos = new Float32Array(MAX * 3);
    this.col = new Float32Array(MAX * 3);
    this.vel = new Float32Array(MAX * 3);
    this.life = new Float32Array(MAX);
    this.max = new Float32Array(MAX);
    this.cursor = 0;
    for (let i = 0; i < MAX; i++) this.pos[i * 3 + 1] = -999;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3));
    const mat = new THREE.PointsMaterial({
      size, vertexColors: true, transparent: true, opacity, depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      sizeAttenuation: true,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.geo = geo;
  }
  spawn(position, color, count, speed = 2, up = 2, life = .7, spread = 1) {
    const c = new THREE.Color(color);
    for (let n = 0; n < count; n++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % MAX;
      const a = Math.random() * Math.PI * 2;
      const r = Math.random() * speed * spread;
      this.pos[i * 3] = position.x + (Math.random() - .5) * .25;
      this.pos[i * 3 + 1] = position.y + (Math.random() - .5) * .25;
      this.pos[i * 3 + 2] = position.z + (Math.random() - .5) * .25;
      this.vel[i * 3] = Math.cos(a) * r;
      this.vel[i * 3 + 1] = Math.random() * up + .5;
      this.vel[i * 3 + 2] = Math.sin(a) * r;
      const cc = c.clone().offsetHSL((Math.random() - .5) * .04, 0, (Math.random() - .5) * .25);
      this.col[i * 3] = cc.r; this.col[i * 3 + 1] = cc.g; this.col[i * 3 + 2] = cc.b;
      this.life[i] = life * (.6 + Math.random() * .8);
      this.max[i] = this.life[i];
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
  }
  update(dt) {
    let dirty = false;
    for (let i = 0; i < MAX; i++) {
      if (this.life[i] <= 0) continue;
      this.life[i] -= dt;
      if (this.life[i] <= 0) { this.pos[i * 3 + 1] = -999; dirty = true; continue; }
      this.vel[i * 3 + 1] -= this.gravity * dt;
      this.pos[i * 3] += this.vel[i * 3] * dt;
      this.pos[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
      this.pos[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
      if (this.pos[i * 3 + 1] < .04) {
        this.pos[i * 3 + 1] = .04;
        this.vel[i * 3 + 1] *= -.28;
        this.vel[i * 3] *= .65; this.vel[i * 3 + 2] *= .65;
      }
      dirty = true;
    }
    if (dirty) this.geo.attributes.position.needsUpdate = true;
  }
}

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.sparks = new PointPool(scene, { size: .085, additive: true, opacity: .95, gravity: 7 });
    this.blood = new PointPool(scene, { size: .115, additive: false, opacity: .9, gravity: 12 });
    this.dust = new PointPool(scene, { size: .16, additive: false, opacity: .34, gravity: 1.8 });
    this.tracers = [];
    this.shells = [];
    this.debris = [];
    this.rings = [];
    this.lastBlood = 0;
  }

  shot(from, to) {
    const geo = new THREE.BufferGeometry().setFromPoints([from.clone(), to.clone()]);
    const mat = new THREE.LineBasicMaterial({ color: 0xffdc9c, transparent: true, opacity: .92, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
    const line = new THREE.Line(geo, mat);
    this.scene.add(line);
    this.tracers.push({ line, life: .065, max: .065 });
    this.sparks.spawn(to, 0xffc56f, 8, 3.2, 2.4, .42);
  }

  impact(position) {
    this.sparks.spawn(position, 0xffbd68, 6, 2.5, 1.6, .32);
    this.blood.spawn(position, 0x7d1b1a, 9, 2.0, 1.8, .55);
  }

  zombieHit(position) {
    this.blood.spawn(position, 0x8f1d1b, 11, 2.2, 2.2, .62);
    const now = performance.now();
    if (now - this.lastBlood > 70) {
      this.lastBlood = now;
      this.blood.spawn(position, 0x4a0f10, 5, 1.5, 1.4, .45);
    }
  }

  zombieDeath(position) {
    this.blood.spawn(position, 0x731515, 26, 2.8, 2.7, .85);
    this.blood.spawn(position, 0x3c0b0c, 12, 1.5, 1.3, 1.1);
    this.dust.spawn(position.clone().setY(.18), 0x8d7d6e, 9, 2.6, .7, .9);
    this.ring(position.clone().setY(.04), 0x8d1b18, .45, 2.4, .42);
  }

  barrierHit(position) {
    this.sparks.spawn(position, 0xffc47a, 5, 2.2, 1.2, .3);
    this.dust.spawn(position, 0x9f8e75, 5, 1.5, .8, .5);
  }

  breach(position) {
    this.dust.spawn(position.clone().setY(.4), 0x9c8972, 24, 4.5, 2.4, 1.2);
    this.sparks.spawn(position.clone().setY(.7), 0xffa14d, 14, 3.0, 2.0, .5);
    this.ring(position.clone().setY(.05), 0xb08d65, 1, 4.8, .8);
  }

  repair(position) {
    this.sparks.spawn(position, 0xffd583, 13, 2.4, 2.1, .5);
    this.dust.spawn(position, 0xb8a17f, 6, 1.4, .8, .6);
  }

  trap(position) {
    this.sparks.spawn(position, 0xffb85e, 15, 3.5, 2.0, .45);
    this.dust.spawn(position, 0x8a7662, 5, 1.8, .6, .5);
    this.ring(position.clone().setY(.04), 0xb83227, .5, 2.8, .35);
  }

  muzzle(position) {
    this.sparks.spawn(position, 0xffd07a, 4, 1.8, .7, .16);
  }

  shell(position, dir) {
    const geo = new THREE.CylinderGeometry(.018, .018, .075, 6);
    const mat = new THREE.MeshBasicMaterial({ color: 0xe2ad55, toneMapped: false });
    const m = new THREE.Mesh(geo, mat);
    m.position.copy(position);
    this.scene.add(m);
    this.shells.push({
      mesh: m, life: 2.1,
      vel: new THREE.Vector3((Math.random() - .5) * 1.5 + dir.x * .5, 2.6 + Math.random(), (Math.random() - .5) * 1.5 + dir.z * .5),
      rot: new THREE.Vector3(Math.random() * 8, Math.random() * 8, Math.random() * 8),
    });
  }

  debrisBurst(barrierGroup) {
    const wood = new THREE.MeshStandardMaterial({ color: 0x74563c, roughness: .9, flatShading: true });
    for (let i = 0; i < 14; i++) {
      const m = new THREE.Mesh(new THREE.BoxGeometry(.12 + Math.random() * .35, .07 + Math.random() * .12, .06 + Math.random() * .16), wood);
      const wp = new THREE.Vector3((Math.random() - .5) * 6.5, .4 + Math.random() * 2.1, (Math.random() - .5) * .3);
      barrierGroup.localToWorld(wp);
      m.position.copy(wp);
      this.scene.add(m);
      this.debris.push({
        mesh: m, life: 2.4,
        vel: new THREE.Vector3((Math.random() - .5) * 4.5, 2.2 + Math.random() * 3.5, (Math.random() - .5) * 4.5),
        rot: new THREE.Vector3(Math.random() * 6, Math.random() * 6, Math.random() * 6),
      });
    }
  }

  ring(position, color = 0xffaa55, scale = 1, duration = .55, opacity = .5) {
    const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const m = new THREE.Mesh(new THREE.RingGeometry(.25, .36, 24), mat);
    m.rotation.x = -Math.PI / 2;
    m.position.copy(position);
    m.scale.setScalar(scale * .4);
    this.scene.add(m);
    this.rings.push({ mesh: m, life: duration, max: duration, scale, opacity });
  }

  update(dt) {
    this.sparks.update(dt);
    this.blood.update(dt);
    this.dust.update(dt);
    for (let i = this.tracers.length - 1; i >= 0; i--) {
      const t = this.tracers[i];
      t.life -= dt;
      t.line.material.opacity = Math.max(0, t.life / t.max) * .92;
      if (t.life <= 0) { this.scene.remove(t.line); t.line.geometry.dispose(); t.line.material.dispose(); this.tracers.splice(i, 1); }
    }
    for (let i = this.shells.length - 1; i >= 0; i--) {
      const s = this.shells[i];
      s.life -= dt;
      s.vel.y -= 9.5 * dt;
      s.mesh.position.addScaledVector(s.vel, dt);
      s.mesh.rotation.x += s.rot.x * dt; s.mesh.rotation.y += s.rot.y * dt;
      if (s.mesh.position.y < .03) { s.mesh.position.y = .03; s.vel.y *= -.3; s.vel.x *= .7; s.vel.z *= .7; }
      if (s.life <= 0) { this.scene.remove(s.mesh); s.mesh.geometry.dispose(); s.mesh.material.dispose(); this.shells.splice(i, 1); }
    }
    for (let i = this.debris.length - 1; i >= 0; i--) {
      const d = this.debris[i];
      d.life -= dt;
      d.vel.y -= 12 * dt;
      d.mesh.position.addScaledVector(d.vel, dt);
      d.mesh.rotation.x += d.rot.x * dt; d.mesh.rotation.y += d.rot.y * dt;
      if (d.mesh.position.y < .05) { d.mesh.position.y = .05; d.vel.y *= -.24; d.vel.x *= .72; d.vel.z *= .72; d.rot.multiplyScalar(.75); }
      if (d.life <= 0) {
        d.mesh.material.opacity = Math.max(0, d.life);
        if (d.life < -.8) { this.scene.remove(d.mesh); d.mesh.geometry.dispose(); this.debris.splice(i, 1); }
      }
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      const p = 1 - r.life / r.max;
      r.mesh.scale.setScalar(r.scale * (.4 + p * 1.8));
      r.mesh.material.opacity = r.opacity * (1 - p);
      if (r.life <= 0) { this.scene.remove(r.mesh); r.mesh.geometry.dispose(); r.mesh.material.dispose(); this.rings.splice(i, 1); }
    }
  }

  clear() {
    this.tracers.forEach(t => { this.scene.remove(t.line); t.line.geometry.dispose(); t.line.material.dispose(); });
    this.tracers = [];
    this.shells.forEach(s => { this.scene.remove(s.mesh); s.mesh.geometry.dispose(); s.mesh.material.dispose(); });
    this.shells = [];
    this.debris.forEach(d => { this.scene.remove(d.mesh); d.mesh.geometry.dispose(); });
    this.debris = [];
    this.rings.forEach(r => { this.scene.remove(r.mesh); r.mesh.geometry.dispose(); r.mesh.material.dispose(); });
    this.rings = [];
    this.sparks.life.fill(0); this.blood.life.fill(0); this.dust.life.fill(0);
    this.sparks.pos.fill(-999); this.blood.pos.fill(-999); this.dust.pos.fill(-999);
    this.sparks.geo.attributes.position.needsUpdate = true;
    this.blood.geo.attributes.position.needsUpdate = true;
    this.dust.geo.attributes.position.needsUpdate = true;
  }
}

const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];

const WAVE_TITLES = [
  'THE FIRST KNOCK',
  'UNPAID GUESTS',
  'THE DINER CROWD',
  'FULL HOUSE',
  'CHECKOUT TIME',
  'LAST CALL',
];

export class UI {
  constructor() {
    this.hud = $('#hud');
    this.start = $('#start-screen');
    this.pause = $('#pause-screen');
    this.end = $('#end-screen');
    this.lock = $('#target-lock');
    this.healthFill = $('#health-fill');
    this.healthText = $('#health-text');
    this.statusRow = $('.status-row');
    this.statusText = $('#status-text');
    this.shells = $('#shells');
    this.reloadLabel = $('#reload-label');
    this.score = $('#score');
    this.scrap = $('#scrap');
    this.waveTitle = $('#wave-title');
    this.waveState = $('#wave-state');
    this.nightLabel = $('#night-label');
    this.waveProgress = $('#wave-progress');
    this.clearBanner = $('#clear-banner');
    this.breakBanner = $('#break-banner');
    this.breakCount = $('#break-count');
    this.clearBonus = $('#clear-bonus');
    this.toasts = $('#toast-stack');
    this.damageFlash = $('#damage-flash');
    this.lowHealth = $('#low-health');
    this.objective = $('#objective');
    this.objectiveTitle = $('#objective-title');
    this.objectiveSub = $('#objective-sub');
    this.repairBtn = $('#repair-btn');
    this.trapBtn = $('#trap-btn');
    this.fireBtn = $('#fire-btn');
    this.barrierRows = $$('.barricade-row');
    this.muteBtn = $('#mute-btn');
    this.lastShells = -1;
    this.lastHealth = -1;
    this.lastScrap = -1;
    this.lastScore = -1;
    this.floatEls = [];
    this.toastTimers = [];
    this.endStamp = $('#end-stamp');
    this.endKicker = $('#end-kicker');
    this.endTitle = $('#end-title');
    this.endCopy = $('#end-copy');
  }

  setPlaying(on) {
    this.hud.classList.toggle('hidden', !on);
  }

  hideStart() {
    this.start.classList.add('leaving');
    setTimeout(() => this.start.classList.add('hidden'), 620);
  }

  showStart() {
    this.start.classList.remove('hidden', 'leaving');
    this.hud.classList.add('hidden');
    this.end.classList.add('hidden');
    this.pause.classList.add('hidden');
  }

  showHud() {
    this.hud.classList.remove('hidden');
    this.objective.classList.remove('fade');
  }

  setMuted(muted) {
    this.muteBtn.classList.toggle('muted', muted);
    this.muteBtn.setAttribute('aria-label', muted ? 'Unmute sound' : 'Mute sound');
  }

  setHealth(hp, max, hurt = false) {
    const pct = Math.max(0, hp / max);
    if (this.lastHealth !== Math.round(hp)) {
      this.healthFill.style.width = `${pct * 100}%`;
      this.healthText.textContent = Math.max(0, Math.ceil(hp));
      this.lowHealth.classList.toggle('on', pct < .35);
      this.statusRow.classList.toggle('hurt', pct < .45 || hurt);
      this.statusText.textContent = pct < .2 ? 'CRITICAL' : pct < .45 ? 'BLEEDING' : hurt ? 'STUNG' : 'STEADY';
      this.healthFill.style.background = pct < .3
        ? 'linear-gradient(90deg,#7d1717,#e23b31)'
        : pct < .55
          ? 'linear-gradient(90deg,#a83731,#f28d4a)'
          : 'linear-gradient(90deg,#a83731,#d74b40 60%,#ee7054)';
      this.lastHealth = Math.round(hp);
    }
  }

  setScore(score) {
    if (score === this.lastScore) return;
    this.lastScore = score;
    this.score.textContent = String(Math.max(0, Math.floor(score))).padStart(6, '0');
  }

  setScrap(scrap) {
    if (scrap === this.lastScrap) return;
    this.lastScrap = scrap;
    this.scrap.textContent = String(scrap).padStart(2, '0');
  }

  setAmmo(shells, max, reloading) {
    if (shells !== this.lastShells) {
      this.lastShells = shells;
      if (this.shells.children.length !== max) {
        this.shells.innerHTML = '';
        for (let i = 0; i < max; i++) {
          const s = document.createElement('i');
          s.className = 'shell';
          this.shells.appendChild(s);
        }
      }
      [...this.shells.children].forEach((el, i) => el.classList.toggle('empty', i >= shells));
    }
    this.reloadLabel.classList.toggle('hidden', !reloading);
  }

  setWave(index, total, phase, timeLeft = 0) {
    const n = String(index + 1).padStart(2, '0');
    this.nightLabel.textContent = `NIGHT ${n}`;
    if (phase === 'break') {
      this.waveState.textContent = 'REGROUP';
      this.waveTitle.textContent = 'THEY COME IN WAVES';
    } else if (phase === 'victory') {
      this.waveState.textContent = 'DAWN';
      this.waveTitle.textContent = 'SUNRISE';
    } else {
      this.waveState.textContent = `WAVE ${index + 1} / ${total}`;
      this.waveTitle.textContent = WAVE_TITLES[index] || 'HOLD THE LINE';
    }
  }

  setWaveProgress(pct) {
    this.waveProgress.style.width = `${Math.min(1, Math.max(0, pct)) * 100}%`;
  }

  setBarriers(barriers) {
    barriers.forEach((b, i) => {
      const row = this.barrierRows[i];
      if (!row) return;
      const pct = Math.max(0, b.hp / b.maxHp);
      row.querySelector('.mini-bar span').style.width = `${pct * 100}%`;
      row.querySelector('b').textContent = b.destroyed ? 'OPEN' : `${Math.round(pct * 100)}%`;
      row.classList.toggle('crit', pct < .3 || b.destroyed);
      row.classList.toggle('warn', pct >= .3 && pct < .6);
    });
  }

  setRepairReady(ready) {
    this.repairBtn.classList.toggle('armed', ready);
  }

  showTarget(worldPos, camera, active = true) {
    if (!active || !worldPos) {
      this.lock.classList.add('hidden');
      return;
    }
    const p = worldPos.clone().project(camera);
    if (p.z > 1 || p.z < -1 || Math.abs(p.x) > 1.2 || Math.abs(p.y) > 1.2) {
      this.lock.classList.add('hidden');
      return;
    }
    const x = (p.x * .5 + .5) * window.innerWidth;
    const y = (-p.y * .5 + .5) * window.innerHeight;
    this.lock.style.left = `${x}px`;
    this.lock.style.top = `${y}px`;
    this.lock.classList.remove('hidden');
  }

  hitPulse(crit = false) {
    this.lock.style.transform = 'translate(-50%, -50%) scale(1.3)';
    this.lock.querySelector('span').style.color = crit ? '#ffdc86' : '#d74b40';
    clearTimeout(this.hitTimer);
    this.hitTimer = setTimeout(() => {
      if (this.lock) {
        this.lock.style.transform = 'translate(-50%, -50%) scale(1)';
        this.lock.querySelector('span').style.color = '#d74b40';
      }
    }, 90);
  }

  damage() {
    this.damageFlash.classList.add('hit');
    clearTimeout(this.damageTimer);
    this.damageTimer = setTimeout(() => this.damageFlash.classList.remove('hit'), 100);
  }

  toast(text, type = '') {
    const el = document.createElement('div');
    el.className = `toast ${type}`;
    el.textContent = text;
    this.toasts.appendChild(el);
    const t = setTimeout(() => el.remove(), 2200);
    this.toastTimers.push(t);
  }

  objectiveSet(title, sub) {
    this.objectiveTitle.textContent = title;
    this.objectiveSub.textContent = sub;
    this.objective.classList.remove('fade');
  }

  fadeObjective() { this.objective.classList.add('fade'); }

  showClear(bonus, seconds) {
    this.clearBanner.classList.remove('hidden');
    this.clearBonus.textContent = `+${bonus} SCRAP`;
    setTimeout(() => this.clearBanner.classList.add('hidden'), 3300);
  }

  showBreak(seconds) {
    this.breakBanner.classList.remove('hidden');
    this.breakCount.textContent = `00:0${Math.max(0, Math.ceil(seconds))}`;
    this.breakCount.style.color = seconds < 3 ? '#d74b40' : '';
  }

  updateBreak(seconds) {
    this.breakCount.textContent = `00:0${Math.max(0, Math.ceil(seconds))}`;
    this.breakCount.style.color = seconds < 3 ? '#d74b40' : '';
  }

  hideBreak() { this.breakBanner.classList.add('hidden'); }

  floatText(worldPos, camera, text, cls = '') {
    const p = worldPos.clone().project(camera);
    if (p.z > 1) return;
    const x = (p.x * .5 + .5) * window.innerWidth;
    const y = (-p.y * .5 + .5) * window.innerHeight;
    const el = document.createElement('div');
    el.className = `damage-num ${cls}`;
    el.textContent = text;
    el.style.left = `${x + (Math.random() - .5) * 20}px`;
    el.style.top = `${y}px`;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 900);
  }

  showPause(on) {
    this.pause.classList.toggle('hidden', !on);
  }

  showEnd({ victory, waves, kills, score, best }) {
    this.end.classList.remove('hidden');
    this.hud.classList.add('hidden');
    this.endStamp.textContent = victory ? 'SURVIVED' : 'YOU DIED';
    this.endStamp.style.webkitTextStroke = victory ? '2px rgba(242,167,59,.55)' : '2px rgba(215,75,64,.48)';
    this.endKicker.textContent = victory ? 'THE SUN CAME UP' : 'THE NIGHT WINS';
    this.endTitle.innerHTML = victory ? 'THE ROAD IS<br/>YOURS AGAIN.' : 'THE MOTEL<br/>KEEPS ITS GUESTS.';
    this.endCopy.textContent = victory
      ? 'Six waves. One busted shotgun. A sunrise worth waiting for.'
      : 'They got through the line. They always do. But the night can be beaten.';
    $('#stat-wave').textContent = `${waves} / 6`;
    $('#stat-kills').textContent = String(kills);
    $('#stat-score').textContent = String(score).padStart(6, '0');
    $('#stat-best').textContent = String(best).padStart(6, '0');
  }

  hideEnd() {
    this.end.classList.add('hidden');
  }

  reset() {
    this.setScore(0); this.setScrap(0); this.setHealth(100, 100);
    this.setAmmo(8, 8, false);
    this.clearBanner.classList.add('hidden');
    this.breakBanner.classList.add('hidden');
    this.lock.classList.add('hidden');
    this.lowHealth.classList.remove('on');
    this.toasts.innerHTML = '';
    this.setRepairReady(false);
  }
}

