152:   const bob = Math.abs(Math.sin(t * 10.5)) * .045 * s;
153:   p.leftLeg.rotation.x = walk;
154:   p.rightLeg.rotation.x = -walk;
155:   p.leftArm.rotation.x = -walk * .62 + .08;
156:   p.rightArm.rotation.x = walk * .35 - .3;
157:   p.leftArm.rotation.z = .06;
158:   p.rightArm.rotation.z = -.16;
159:   p.body.position.y = bob + Math.sin(t * 1.8) * .012;
