import { chromium } from '/home/runner/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.mjs';

const BASE = 'http://localhost:3002';
const errors = [];

async function track(page, tag) {
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(`[${tag}] console: ${msg.text()}`);
  });
  page.on('pageerror', (err) => errors.push(`[${tag}] pageerror: ${err.message}`));
}

async function boot(browser, viewport, isMobile) {
  const context = await browser.newContext({
    viewport,
    isMobile,
    hasTouch: isMobile,
    deviceScaleFactor: 1,
  });
  const page = await context.newPage();
  await track(page, isMobile ? 'mobile' : 'desktop');
  await page.goto(BASE, { waitUntil: 'networkidle' });
  await page.waitForFunction(() => window.__deadBlock && document.body.classList.contains('ready'), null, { timeout: 30000 });
  return { context, page };
}

const browser = await chromium.launch({ args: ['--autoplay-policy=no-user-gesture-required'] });

// ---------- DESKTOP ----------
const desk = await boot(browser, { width: 1280, height: 800 }, false);
await desk.page.click('#start-btn');
await desk.page.waitForFunction(() => window.__deadBlock.phase === 'wave');

// warm up the simulation so zombies are on screen
await desk.page.evaluate(() => {
  for (let i = 0; i < 420; i++) window.__deadBlock.update(1 / 60);
});

const rebuild = await desk.page.evaluate(() => {
  const g = window.__deadBlock;
  const b = g.world.barriers[0];
  // stand next to the barricade and breach it
  g.playerPos.set(b.pos.x, 0, b.pos.z - 1.6);
  g.player.root.position.copy(g.playerPos);
  b.destroyed = true;
  b.hp = 0;
  b.planks.forEach(p => p.visible = false);
  b.shake = 0;
  g.scrap = 9;
  g.ui.setBarriers(g.world.barriers);
  const scrapBefore = g.scrap;
  // fire the repair action through the real UI control path
  const btn = document.getElementById('repair-btn');
  btn.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, pointerId: 1 }));
  const row = document.querySelectorAll('.barricade-row')[0];
  return {
    scrapBefore,
    scrapAfter: g.scrap,
    destroyed: b.destroyed,
    hp: b.hp,
    maxHp: b.maxHp,
    rowLabel: row.querySelector('b').textContent,
    toast: document.getElementById('toast')?.textContent ?? '',
    paused: g.paused,
    phase: g.phase,
  };
});

const patch = await desk.page.evaluate(() => {
  const g = window.__deadBlock;
  const b = g.world.barriers[0];
  g.playerPos.set(b.pos.x, 0, b.pos.z - 1.6);
  b.hp = 100;
  g.scrap = 6;
  const before = b.hp;
  const btn = document.getElementById('repair-btn');
  btn.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, pointerId: 1 }));
  return { before, after: b.hp, maxHp: b.maxHp, scrap: g.scrap };
});

// run a little more so combat/UI are live for the screenshot
await desk.page.evaluate(() => {
  const g = window.__deadBlock;
  g.playerPos.set(0, 0, 2.2);
  g.player.root.position.copy(g.playerPos);
  for (let i = 0; i < 180; i++) g.update(1 / 60);
  g.controls.firing = true;
  for (let i = 0; i < 40; i++) g.update(1 / 60);
  g.controls.firing = false;
});

await desk.page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-desktop.jpg', type: 'jpeg', quality: 62, timeout: 60000 });

// ---------- MOBILE ----------
const mob = await boot(browser, { width: 390, height: 844 }, true);
await mob.page.tap('#start-btn');
await mob.page.waitForFunction(() => window.__deadBlock.phase === 'wave');
await mob.page.evaluate(() => {
  const g = window.__deadBlock;
  for (let i = 0; i < 360; i++) g.update(1 / 60);
});
await mob.page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/final-mobile.jpg', type: 'jpeg', quality: 62, timeout: 60000 });

const mobileState = await mob.page.evaluate(() => {
  const g = window.__deadBlock;
  return {
    phase: g.phase,
    wave: g.waveIndex,
    scrap: g.scrap,
    hp: g.hp,
    touchClass: document.body.className,
    joystick: !!document.querySelector('#joystick, .joystick'),
    repairVisible: getComputedStyle(document.getElementById('repair-btn')).display,
  };
});

await browser.close();

console.log(JSON.stringify({ rebuild, patch, mobileState, errors }, null, 2));

